canonical:
class Shape:
    def __init__(self, name):
        self.name = name

    def describe(self):
        return f'{self.name}: no area defined'


class Square(Shape):
    def __init__(self, side):
        super().__init__('square')
        self.side = side

    def describe(self):
        return f'square: area is {self.side * self.side}'
